using Inventory.Core.Services;
using Inventory.Core.Models;
using Microsoft.AspNetCore.Mvc;

namespace Inventory.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class WarehouseController : ControllerBase
{
    private readonly IStockService _stockService;
    private readonly ILogger<WarehouseController> _logger;

    public WarehouseController(IStockService stockService, ILogger<WarehouseController> logger)
    {
        _stockService = stockService;
        _logger = logger;
    }

    [HttpGet("{warehouseId}/stock")]
    public async Task<IActionResult> GetStockLevels(int warehouseId, [FromQuery] int page = 1, int pageSize = 50)
    {
        if (pageSize > 200) pageSize = 200;
        var levels = await _stockService.GetLevelsAsync(warehouseId, page, pageSize);
        return Ok(levels);
    }

    [HttpPost("transfer")]
    public async Task<IActionResult> TransferStock([FromBody] StockTransferRequest request)
    {
        var result = await _stockService.TransferAsync(request);
        if (!result.Succeeded) return Conflict(result.Error);
        _logger.LogInformation("Transferred {Qty} units of SKU {Sku}", request.Quantity, request.Sku);
        return NoContent();
    }
}

