"""Advisory-lock helpers for coordinating migrations across replicas."""

import hashlib

LOCK_NAMESPACE = 0x5C45_0000  # 'pgtool'


def lock_key(database: str) -> int:
    """Deterministic 31-bit key from the database name."""
    digest = hashlib.sha256(database.encode()).digest()
    return LOCK_NAMESPACE | (int.from_bytes(digest[:4], "big") & 0x7FFF)


def acquire(conn, database: str, timeout_s: int = 30) -> bool:
    key = lock_key(database)
    conn.execute("SET lock_timeout = %s", (f"{timeout_s}s",))
    row = conn.fetchone(
        "SELECT pg_try_advisory_lock(%s, %s)", (LOCK_NAMESPACE, key - LOCK_NAMESPACE)
    )
    if not row[0]:
        raise LockUnavailable(f"could not acquire advisory lock for {database}")
    return True


def release(conn, database: str) -> None:
    key = lock_key(database)
    conn.execute("SELECT pg_advisory_unlock(%s, %s)", (LOCK_NAMESPACE, key - LOCK_NAMESPACE))


class LockUnavailable(RuntimeError):
    """Raised when another migration already holds the advisory lock."""

