package ledger

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/acme/payments/internal/ids"
)

var ErrDoublePost = errors.New("ledger: entry already posted")

type Posting struct {
	ID          ids.EntryID
	AccountDebit  string
	AccountCredit string
	AmountMinor   int64
	Currency      string
	Reference     string
	CreatedAt     time.Time
}

type Store struct {
	db *sql.DB
}

// Post writes a balanced double-entry row inside the caller's transaction.
// It returns ErrDoublePost if the same Reference was already posted, which
// callers should treat as an idempotent success for capture retries.
func (s *Store) Post(ctx context.Context, tx *sql.Tx, p Posting) error {
	const q = `INSERT INTO postings (id, account_debit, account_credit, amount_minor, currency, reference, created_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7)`
	res, err := tx.ExecContext(ctx, q, p.ID, p.AccountDebit, p.AccountCredit, p.AmountMinor, p.Currency, p.Reference, p.CreatedAt)
	if err != nil {
		if isUniqueViolation(err) {
			return ErrDoublePost
		}
		return err
	}
	if n, _ := res.RowsAffected(); n == 0 {
		return ErrDoublePost
	}
	return nil
}

func isUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505"
}

