class RevenueNormalizerSpec extends AnyFunSuite {

  implicit lazy val spark: SparkSession = TestSessionProvider.session
  import spark.implicits._

  val normalizer = new RevenueNormalizer(spark, "fx_snapshot")

  test("joins daily FX rates on currency pair") {
    val sample = Seq(
      ("t1", 100.0, "EUR", "USD"),
      ("t2", 250.0, "GBP", "USD")
    ).toDF("txn_id", "amount", "from_ccy", "to_ccy")
