    val sample = Seq(
      ("t3", 900.0, "JPY", "USD")
    ).toDF("txn_id", "amount", "from_ccy", "to_ccy")
    val result = normalizer.normalize(sample, "2024-03-01")
    assert(result.quarantine.count() == 1)
  }
}

