import 'dart:math' as math;

class EtaCalculator {
  EtaCalculator({this.defaultSpeedKmh = 28});

  final double defaultSpeedKmh;

  /// Rough ETA in minutes using haversine distance and average city speed.
  int estimateMinutes({required double lat1, required double lng1, required double lat2, required double lng2}) {
    final km = _haversine(lat1, lng1, lat2, lng2) * 1.3; // road factor
    final minutes = (km / defaultSpeedKmh) * 60;
    return math.max(2, minutes.round());
  }

  double _haversine(double lat1, double lng1, double lat2, double lng2) {
    final dLat = _rad(lat2 - lat1);
    final dLng = _rad(lng2 - lng1);
    final a = math.pow(math.sin(dLat / 2), 2) +
        math.cos(_rad(lat1)) * math.cos(_rad(lat2)) * math.pow(math.sin(dLng / 2), 2);
    return 6371 * 2 * math.asin(math.sqrt(a));
  }

  double _rad(double deg) => deg * math.pi / 180;
}

