import torch
import torch.nn as nn
from torchvision.models import resnet50


class ResNetAdapter(nn.Module):
    """Wraps a pretrained ResNet-50 with a small bottleneck adapter."""

    def __init__(self, num_classes: int = 365, bottleneck: int = 256):
        super().__init__()
        base = resnet50(weights="IMAGENET1K_V2")
        self.backbone = nn.Sequential(*list(base.children())[:-1])
        for p in self.backbone.parameters():
            p.requires_grad = False
        self.adapter = nn.Sequential(
            nn.Linear(2048, bottleneck),
            nn.GELU(),
            nn.Dropout(0.1),
            nn.Linear(bottleneck, num_classes),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            feats = self.backbone(x).flatten(1)
        return self.adapter(feats)

    def trainable_params(self):
        return [p for p in self.parameters() if p.requires_grad]

