#include "thermostat.h"
#include "nvs_flash.h"
#include "driver/adc.h"

#define HYSTERESIS_C 0.5f
#define MIN_CALL_INTERVAL_MS 30000

static float last_setpoint = 21.0f;
static bool relay_state = false;
static TickType_t last_switch_tick = 0;

static float read_temperature(void) {
    uint32_t raw = adc1_get_raw(ADC_CHANNEL_6);
    float mv = raw * 3300.0f / 4095.0f;
    return (mv - 500.0f) / 10.0f; // TMP36, 10 mV/degC, 500 mV offset
}

bool thermostat_should_heat(float setpoint) {
    float temp = read_temperature();
    TickType_t now = xTaskGetTickCount();

    if ((now - last_switch_tick) < pdMS_TO_TICKS(MIN_CALL_INTERVAL_MS)) {
        return relay_state; // enforce min cycle time on relay
    }

    bool want;
    if (relay_state) {
        want = temp < (setpoint - HYSTERESIS_C);
    } else {
        want = temp < (setpoint - 2.0f * HYSTERESIS_C);
    }

    if (want != relay_state) {
        relay_state = want;
        last_switch_tick = now;
        relay_set(HEAT_RELAY, want);
        nvs_save_setpoint(setpoint);
    }
    return relay_state;
}

void thermostat_set_setpoint(float sp) {
    if (sp > 10.0f && sp < 30.0f) {
        last_setpoint = sp;
    }
}

