package com.acornbank.transfer;

import com.acornbank.account.AccountRepository;
import com.acornbank.audit.AuditLog;
import com.acornbank.audit.AuditLogger;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.util.UUID;

@Service
public class TransferService {

    private final AccountRepository accounts;
    private final SepaClient sepa;
    private final AuditLogger audit;
    private final Clock clock;

    private static final BigDecimal DAILY_LIMIT = new BigDecimal("25000.00");

    public TransferService(AccountRepository accounts, SepaClient sepa,
                           AuditLogger audit, Clock clock) {
        this.accounts = accounts;
        this.sepa = sepa;
        this.audit = audit;
        this.clock = clock;
    }

    @Transactional
    public TransferResult execute(TransferRequest request) {
        if (request.fromIban().equals(request.toIban())) {
            throw new SameAccountTransferException(request.fromIban(), request.toIban());
        }
        if (request.amount().compareTo(DAILY_LIMIT) > 0) {
            throw new TransferLimitExceededException(DAILY_LIMIT, request.amount());
        }

        var from = accounts.lockByIban(request.fromIban())
                .orElseThrow(() -> new AccountClosedException(request.fromIban()));
        var to = accounts.lockByIban(request.toIban())
                .orElseThrow(() -> new AccountClosedException(request.toIban()));

        from.debit(request.amount());
        to.credit(request.amount());

        var reference = "SEPA" + UUID.randomUUID().toString().replace("-", "").substring(0, 12).toUpperCase();
        sepa.submit(reference, request);

        audit.write(new AuditLog("TRANSFER_EXECUTED", from.getCustomerId(), Instant.now(clock)));
        return new TransferResult(reference, from.getBalance());
    }
}

/**
 * Content script: in-page highlight handling for QuickNotes.
 */
const MARK_ATTR = 'data-qn-id';
let observer: MutationObserver | null = null;

export function initHighlighter() {
  document.addEventListener('dblclick', onDoubleClick);
  observer = new MutationObserver(pruneDetachedMarks);
  observer.observe(document.body, { childList: true, subtree: true });
}

function onDoubleClick(event: MouseEvent) {
  const sel = window.getSelection();
  if (!sel || sel.isCollapsed) return;
  const anchor = sel.anchorNode?.parentElement;
  if (!anchor || anchor.closest('input, textarea, [contenteditable]')) return;
  const range = sel.getRangeAt(0);
  const mark = document.createElement('mark');
  mark.setAttribute(MARK_ATTR, crypto.randomUUID());
  try {
    range.surroundContents(mark);
  } catch {
    mark.appendChild(range.extractContents());
    range.insertNode(mark);
  }
  chrome.runtime.sendMessage({ type: 'SAVE_HIGHLIGHT', text: sel.toString(), url: location.href });
}

function pruneDetachedMarks() {
  document.querySelectorAll(`mark[${MARK_ATTR}]`).forEach((m) => {
    if (!m.textContent?.trim()) m.remove();
  });
}

export function teardown() {
  document.removeEventListener('dblclick', onDoubleClick);
  observer?.disconnect();
  observer = null;
}

if (document.readyState !== 'loading') initHighlighter();
else document.addEventListener('DOMContentLoaded', initHighlighter);

