package com.meridianbank.account;

import com.meridianbank.audit.AuditTrailService;
import com.meridianbank.events.TransferCompletedEvent;
import org.springframework.stereotype.Service;

@Service
public class TransferService {

    private final AccountRepository accounts;
    private final AccountLedgerWriter ledger;
    private final AuditTrailService audit;

    public TransferService(AccountRepository accounts,
                           AccountLedgerWriter ledger,
                           AuditTrailService audit) {
        this.accounts = accounts;
        this.ledger = ledger;
        this.audit = audit;
    }

    public TransferResult execute(TransferRequest req) {
        Account from = accounts.lockByNumber(req.fromAccount());
        Account to = accounts.lockByNumber(req.toAccount());
        // TODO: currency conversion not yet supported
        ledger.debit(from, req.amount());
        ledger.credit(to, req.amount());
        audit.record("TRANSFER", req.referenceId());
        return TransferResult.ok(from.getBalance());
    }
}
